head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS90012.xml';
scwin.vMktactCd = '305'; //채권시장조치구분코드
scwin.pBndApplId = '';
scwin.vBndListProcsTpCd = 1; //채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.arrPar = new Array();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vViewYN = 'Y';
scwin.vIsuCd = '';
scwin.vStripAmtCfm, scwin.vRegYn = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.pBndApplId = scwin.arrPar[0].BND_APPL_ID;
    }
};



/********************************************** 
 * 함수명  	 : fn_dtl_sync
 * 설명       : 상세조회
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var dsNm = 'BNS_ISU_CHG_INFO';
    var qryId = 'lds.stf.bnsisuchg.select.readIsuChgInfoAmtMmDdAdd';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_BND_APPL_ID=' + scwin.pBndApplId;
    param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명  	 : fn_addPub_sync
 * 설명       : 추가발행내역 조회
 ***********************************************/
scwin.fn_addPub_sync = function() {
    var dsNm = 'BNS_ADD_PUB_DESC';
    var qryId = 'lds.stf.bnsisuchg.select.listAddPubDesc';
    var param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_ISU_CD=' + scwin.vIsuCd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_AddHistory, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    scwin.arrPar[0] = {
        //첨부문서 목록 팝업	
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    scwin.arrPar[0] = {
        STD_CD: dts_DtlInfo.getCellData(1, "ISU_CD"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetAddAndStripMktactAmtCfm
 * 설명       : 추가상장/스트립 동시 시장조치 금액확인 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetAddAndStripMktactAmtCfm = function(arrPar) {
    scwin.arrPar[0] = {
        VIEW_YN: scwin.vStripAmtCfm,
        BND_MKTACT_TP_CD: scwin.vMktactCd,
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD"),
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        ADD_ISU_AMT: dts_DtlInfo.getCellData(1, "ADD_ISU_AMT"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetRegYnReturn
 * 설명       : 추가상장/스트립 동시 시장조치 금액확인 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetRegYnReturn = function(arrPar) {
    scwin.vRegYn = scwin.arrPar[0].REG_YN;
};


/********************************************** 
 * 함수명  	 : fn_ChgTab_Act
 * 설명       : 필드 ReadOnly 속성 제거/부여
 ***********************************************/
scwin.fn_ChgTab_Act = function(vBndListProcsTpCd) {
    //낙찰금리, 추가발행일, 추가발행금액
    if (scwin.vBndListProcsTpCd == 1) {
        edt_AddCoupnRt.setReadOnly("true");
        edt_AddIsuDd.setReadOnly("true");
        $c.stf.showObj(img_AddIsuDd, false); //추가발행일 달력
        edt_AddIsuAmt.setReadOnly("true");
    } else if (scwin.vBndListProcsTpCd == 2) {
        edt_AddCoupnRt.setReadOnly("false");
        edt_AddIsuDd.setReadOnly("false");
        $c.stf.showObj(img_AddIsuDd, true); //추가발행일 달력
        edt_AddIsuAmt.setReadOnly("false");
    }
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_Req); //패널라운드처리(신청)
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo); //패널라운드처리(상세)
    $c.bns.BnsPanelToGroupBox(pnl_Acpt); //패널라운드처리(접수)		

    tab_List.setSelectedTabIndex(1);
    scwin.fn_SetParam(); //호출파라미터설정	
    scwin.fn_dtl_sync(); //상세조회
    //필드 ReadOnly 속성 제거/부여
    scwin.fn_ChgTab_Act(scwin.vBndListProcsTpCd);
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vBndListProcsTpCd = nIndex;
    scwin.fn_dtl_sync(); //상세조회
    //필드 ReadOnly 속성 제거/부여
    scwin.fn_ChgTab_Act(scwin.vBndListProcsTpCd);
};
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    scwin.vDtlInfoRowCount = rowcount;

    //당일 스트립 체크 설정
    if (dts_DtlInfo.getCellData(1, "TDD_STRIP_MKTACT_YN") == 'Y') {
        chk_Tdd_StripMktactYn.setValue(1);
    } else {
        chk_Tdd_StripMktactYn.setValue(0);
    }
    scwin.vIsuCd = dts_DtlInfo.getCellData(1, "ISU_CD");
    scwin.fn_addPub_sync(); //추가발행내역 조회

    edt_CoupnRt.RightMargin = 5;
    edt_IsuAmt.RightMargin = 5;
    edt_ListAmt.RightMargin = 5;
    edt_BfchgStripNsprtBal.RightMargin = 5;
    edt_AddCoupnRt.RightMargin = 5;
    edt_TotIsuAmt.RightMargin = 5;
    edt_TotListAmt.RightMargin = 5;
    edt_AfchgStripNsprtBal.RightMargin = 5;
};
scwin.img_StrtDd_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    popUpCalendar2(edt_StrtDd);
};
scwin.img_AddIsuDd_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    popUpCalendar2(edt_AddIsuDd);
};
scwin.btn_Attach_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    if ("N" == dts_DtlInfo.getCellData(dts_DtlInfo.getRowPosition(), "HAS_ATTACH_DOC")) {
        $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
        return;
    }
    scwin.fn_GetPar = fn_GetCommonKey;
    $c.bns.fn_PopAttachDocSearch(lbl_BndApplId);
};
scwin.btn_Dtl_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.fn_GetPar = fn_GetParIsuDelInfo;
    $c.bns.fn_PopIsuDetail(lbl_BndApplId);
};
scwin.img_StripAmtCfm_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    if (chk_Tdd_StripMktactYn.checked == true) {
        scwin.vStripAmtCfm = "View";
        scwin.fn_GetPar = fn_GetAddAndStripMktactAmtCfm;
        scwin.fn_SetPar = fn_SetRegYnReturn;
        $c.bns.fn_PopAddAndStripMktactAmtCfm(lbl_BndApplId);
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.edt_CoupnRt_OnKillFocus = function() {
    edt_CoupnRt.RightMargin = 5;
};
scwin.edt_IsuAmt_OnKillFocus = function() {
    edt_IsuAmt.RightMargin = 5;
};
scwin.edt_ListAmt_OnKillFocus = function() {
    edt_ListAmt.RightMargin = 5;
};
scwin.edt_BfchgStripNsprtBal_OnKillFocus = function() {
    edt_BfchgStripNsprtBal.RightMargin = 5;
};
scwin.edt_AfchgStripNsprtBal_OnKillFocus = function() {
    edt_AfchgStripNsprtBal.RightMargin = 5;
};
scwin.edt_TotListAmt_OnKillFocus = function() {
    edt_TotListAmt.RightMargin = 5;
};
scwin.edt_TotIsuAmt_OnKillFocus = function() {
    edt_TotIsuAmt.RightMargin = 5;
};
scwin.edt_AddCoupnRt_OnKillFocus = function() {
    edt_AddCoupnRt.RightMargin = 5;
};
scwin.dts_DtlInfo_OnColumnChanged = function(row, colid) {
    if (colid == "ADD_ISU_AMT") {
        /** 추가발행금액(화면 자동 계산) */
        if (scwin.vBndListProcsTpCd = 2) {
            $c.stf.setObjectValue(edt_TotIsuAmt, Number($c.stf.getObjectValue(edt_IsuAmt)) + Number($c.stf.getObjectValue(edt_AddIsuAmt)));
            $c.stf.setObjectValue(edt_TotListAmt, Number($c.stf.getObjectValue(edt_ListAmt)) + Number($c.stf.getObjectValue(edt_AddIsuAmt)));
        }
    }
};
